styles:
@font-face{ font-family:"Manrope";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/manrope/v20/xn7gYHE41ni1AdIRggexSg.woff2") format("woff2");font-weight:100 900;font-style:normal;font-display:swap; }
@font-face{ font-family:"Space Grotesk";src:url("https://www.dgeniussolutions.com/wp-content/cache/fonts/1/google-fonts/fonts/s/spacegrotesk/v22/V8mDoQDjQSkFtoMM3T6r8E7mPbF4Cw.woff2") format("woff2");font-weight:300 700;font-style:normal;font-display:swap; }

/* =========================================================
   FULL WIDTH RESET FOR ELEMENTOR / 720P ISSUE
========================================================= */
.dgs-full-bleed {
  width: 100vw !important;
  max-width: 100vw !important;
  margin-left: calc(50% - 50vw) !important;
  margin-right: calc(50% - 50vw) !important;
}
.elementor-widget-html:has(.dgs-case-study-page),
.elementor-widget-container:has(.dgs-case-study-page) {
  width: 100% !important;
  max-width: 100% !important;
}
.dgs-case-study-page,
.dgs-case-study-page * { box-sizing: border-box; }
.dgs-case-study-page {
  position: relative;
  background: #050505;
  color: #fff;
  overflow: hidden;
  font-family: inherit;
  min-height: 100vh;
}
.dgs-cs-container {
  width: 100% !important;
  max-width: 1360px !important;
  margin: 0 auto !important;
  padding-left: clamp(16px, 3vw, 48px) !important;
  padding-right: clamp(16px, 3vw, 48px) !important;
  position: relative;
  z-index: 2;
}
.dgs-wide-container { max-width: 1480px !important; }

/* Background */
.dgs-cs-bg {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(circle at 18% 12%, rgba(47, 107, 255, 0.14), transparent 32%),
    radial-gradient(circle at 82% 24%, rgba(54, 214, 255, 0.13), transparent 34%),
    radial-gradient(circle at 50% 90%, rgba(246, 195, 91, 0.10), transparent 38%),
    #050505;
}
#dgsCaseCanvas { position: absolute; inset: 0; width: 100%; height: 100%; opacity: .45; }
.dgs-bg-orb { position: absolute; border-radius: 999px; filter: blur(55px); opacity: .52; }
.dgs-bg-orb-1 { width: 280px; height: 280px; background: rgba(47,107,255,.25); top: 10%; left: 6%; }
.dgs-bg-orb-2 { width: 320px; height: 320px; background: rgba(54,214,255,.19); top: 44%; right: 4%; }
.dgs-bg-orb-3 { width: 260px; height: 260px; background: rgba(246,195,91,.16); bottom: 8%; left: 42%; }

/* Hero */
.dgs-cs-hero { position: relative; z-index: 2; padding: clamp(80px, 10vw, 130px) 0 clamp(54px, 7vw, 86px); }
.dgs-cs-hero-grid { display: grid; grid-template-columns: minmax(0, 1.08fr) minmax(380px, .92fr); gap: clamp(34px, 5vw, 72px); align-items: center; }
.dgs-cs-eyebrow { display: inline-flex; padding: 9px 16px; border: 1px solid rgba(246,195,91,.3); border-radius: 999px; color: #f6c35b; background: rgba(246,195,91,.08); font-size: 13px; letter-spacing: 1.5px; text-transform: uppercase; margin-bottom: 22px; }
.dgs-cs-hero h1 { margin: 0; font-size: clamp(40px, 6.2vw, 82px); line-height: .98; letter-spacing: -2.4px; font-weight: 800; }
.dgs-cs-hero h1 span { display: block; margin-top: 10px; background: linear-gradient(135deg,#2f6bff,#f6c35b 48%,#36d6ff); -webkit-background-clip: text; -webkit-text-fill-color: transparent; background-clip: text; }
.dgs-cs-hero p { max-width: 780px; margin: 28px 0 0; color: rgba(255,255,255,.72); font-size: 18px; line-height: 1.75; }
.dgs-cs-hero-actions { display: flex; flex-wrap: wrap; gap: 14px; margin-top: 34px; }
.dgs-cs-btn { display: inline-flex; align-items: center; justify-content: center; min-height: 52px; padding: 14px 24px; border-radius: 14px; text-decoration: none !important; font-weight: 800; font-size: 15px; transition: .35s ease; cursor: pointer; border: 0; }
.dgs-cs-btn-primary { color: #fff !important; background: linear-gradient(135deg,#2f6bff,#f6c35b); box-shadow: 0 18px 50px rgba(47,107,255,.24); }
.dgs-cs-btn-primary:hover { transform: translateY(-4px); box-shadow: 0 24px 70px rgba(47,107,255,.38); }
.dgs-cs-btn-secondary { color: #fff !important; background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.14); }
.dgs-cs-btn-secondary:hover { transform: translateY(-4px); border-color: rgba(54,214,255,.45); background: rgba(54,214,255,.08); }
.dgs-cs-hero-stats { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; margin-top: 44px; max-width: 620px; }
.dgs-cs-hero-stats div { padding: 18px; border-radius: 18px; background: rgba(255,255,255,.045); border: 1px solid rgba(255,255,255,.1); }
.dgs-cs-hero-stats strong { display:block; font-size:24px; color:#f6c35b; }
.dgs-cs-hero-stats span { display:block; margin-top:4px; font-size:13px; color:rgba(255,255,255,.58); }

/* Hero 3D */
.dgs-cs-hero-visual { position: relative; min-height: 540px; perspective: 1200px; }
.dgs-hero-device { position: relative; width: min(100%, 560px); margin: 0 auto; border-radius: 28px; background: linear-gradient(145deg,rgba(255,255,255,.14),rgba(255,255,255,.035)); border: 1px solid rgba(255,255,255,.16); box-shadow: 0 35px 120px rgba(0,0,0,.45), inset 0 1px 0 rgba(255,255,255,.12); transform: rotateY(-12deg) rotateX(8deg); transform-style: preserve-3d; overflow: hidden; }
.dgs-device-top { height: 48px; display:flex; align-items:center; gap:9px; padding:0 18px; border-bottom:1px solid rgba(255,255,255,.1); background:rgba(0,0,0,.35); }
.dgs-device-top span { width:11px; height:11px; border-radius:50%; background:rgba(255,255,255,.34); }
.dgs-device-screen { padding:26px; min-height:430px; background: linear-gradient(135deg,rgba(47,107,255,.12),transparent 35%), linear-gradient(225deg,rgba(54,214,255,.13),transparent 38%), rgba(8,8,8,.9); }
.dgs-screen-title { padding:20px; border-radius:20px; background:rgba(255,255,255,.05); border:1px solid rgba(255,255,255,.11); margin-bottom:18px; }
.dgs-screen-title span { display:block; color:#f6c35b; font-size:12px; letter-spacing:1.4px; text-transform:uppercase; margin-bottom:8px; }
.dgs-screen-title h3 { margin:0; font-size:28px; line-height:1.1; }
.dgs-dashboard-bars { height:155px; padding:18px; display:flex; align-items:end; gap:14px; border:1px solid rgba(255,255,255,.11); background:rgba(255,255,255,.04); border-radius:20px; margin-bottom:18px; }
.dgs-dashboard-bars span { flex:1; border-radius:14px 14px 6px 6px; background:linear-gradient(180deg,#36d6ff,#2f6bff); box-shadow:0 0 30px rgba(54,214,255,.23); }
.dgs-dashboard-grid { display:grid; grid-template-columns:1fr 1fr; gap:14px; }
.dgs-dashboard-grid div { padding:16px; border-radius:16px; border:1px solid rgba(255,255,255,.11); background:rgba(255,255,255,.05); }
.dgs-dashboard-grid strong { display:block; font-size:15px; color:#fff; }
.dgs-dashboard-grid span { display:block; margin-top:6px; font-size:12px; color:rgba(255,255,255,.58); }
.dgs-floating-badge { position:absolute; padding:12px 16px; border-radius:999px; border:1px solid rgba(255,255,255,.16); background:rgba(0,0,0,.62); backdrop-filter:blur(12px); color:#fff; font-size:13px; font-weight:800; box-shadow:0 14px 50px rgba(0,0,0,.3); }
.badge-1 { top:70px; left:5px; } .badge-2 { right:0; top:215px; } .badge-3 { bottom:95px; left:65px; }

/* Common */
.dgs-cs-section, .dgs-cs-filter-section, .dgs-cs-process-section, .dgs-cs-final-cta { position: relative; z-index: 2; }
.dgs-cs-filter-section { padding: 36px 0 55px; }
.dgs-cs-section { padding: clamp(58px, 7vw, 90px) 0; }
.dgs-cs-section-heading { text-align:center; max-width:980px; margin:0 auto 48px; }
.dgs-cs-section-heading span, .dgs-final-cta-box span { display:inline-block; color:#36d6ff; font-size:13px; letter-spacing:2px; text-transform:uppercase; margin-bottom:10px; }
.dgs-cs-section-heading h2, .dgs-final-cta-box h2 { margin:0; font-size:clamp(30px,4.2vw,56px); line-height:1.05; letter-spacing:-1.3px; }
.dgs-cs-section-heading p { margin:18px auto 0; color:rgba(255,255,255,.68); font-size:17px; line-height:1.75; }
.dgs-filter-buttons { display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
.dgs-filter-btn { border:1px solid rgba(255,255,255,.16); background:linear-gradient(135deg,rgba(13,132,255,.88),rgba(139,75,255,.78) 48%,rgba(54,214,255,.92)); color:#fff; padding:12px 18px; border-radius:999px; cursor:pointer; font-size:14px; font-weight:800; transition:.3s ease; box-shadow:0 12px 30px rgba(13,132,255,.18); }
.dgs-filter-btn:hover, .dgs-filter-btn.active { color:#fff; border-color:rgba(255,255,255,.48); background:linear-gradient(135deg,#f6c35b,#2f6bff 52%,#36d6ff); transform:translateY(-3px); box-shadow:0 16px 42px rgba(47,107,255,.30); }

/* Website Cards */
.dgs-website-grid { display:grid; gap:36px; }
.dgs-website-card { display:grid; grid-template-columns: minmax(0, 1.18fr) minmax(360px, .82fr); gap:28px; align-items:stretch; padding:24px; border-radius:28px; border:1px solid rgba(255,255,255,.12); background:linear-gradient(135deg,rgba(47,107,255,.07),rgba(54,214,255,.05)),rgba(255,255,255,.035); box-shadow:0 30px 100px rgba(0,0,0,.32); transition:.35s ease; }
.dgs-website-card:hover { transform:translateY(-6px); border-color:rgba(47,107,255,.42); box-shadow:0 28px 90px rgba(47,107,255,.13); }
.dgs-browser-preview { min-height:440px; border-radius:22px; overflow:hidden; border:1px solid rgba(255,255,255,.14); background:rgba(0,0,0,.58); }
.dgs-browser-top { height:48px; display:flex; align-items:center; gap:9px; padding:0 16px; background:rgba(255,255,255,.06); border-bottom:1px solid rgba(255,255,255,.1); }
.dgs-browser-top span { width:11px; height:11px; border-radius:50%; background:rgba(255,255,255,.35); flex:0 0 auto; }
.dgs-browser-top p { margin:0 0 0 8px; width:100%; padding:8px 13px; border-radius:999px; background:rgba(0,0,0,.35); color:rgba(255,255,255,.58); font-size:12px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
.dgs-iframe-wrap { height:392px; background:#111; }
.dgs-iframe-wrap iframe { width:100%; height:100%; border:0; display:block; background:#fff; }
.dgs-website-content { padding:16px; align-self:center; }
.dgs-case-pill { display:inline-flex; color:#f6c35b; background:rgba(246,195,91,.09); border:1px solid rgba(246,195,91,.25); border-radius:999px; padding:8px 13px; font-size:12px; font-weight:800; letter-spacing:1px; text-transform:uppercase; margin-bottom:16px; }
.dgs-website-content h3, .dgs-service-case-card h3, .dgs-process-card h3, .dgs-ai-case-content h3 { margin:0; font-size:32px; line-height:1.12; }
.dgs-website-content p, .dgs-service-case-card p, .dgs-process-card p, .dgs-final-cta-box p, .dgs-ai-case-content p { color:rgba(255,255,255,.68); line-height:1.72; font-size:15.5px; }
.dgs-case-meta { display:grid; grid-template-columns:1fr 1fr; gap:14px; margin:22px 0; }
.dgs-case-meta div { padding:16px; border-radius:16px; background:rgba(255,255,255,.045); border:1px solid rgba(255,255,255,.1); }
.dgs-case-meta span { display:block; color:rgba(255,255,255,.45); font-size:11px; text-transform:uppercase; letter-spacing:1.1px; margin-bottom:8px; }
.dgs-case-meta strong { display:block; color:#fff; font-size:14px; line-height:1.45; }
.dgs-case-tags { display:flex; flex-wrap:wrap; gap:9px; margin-top:18px; }
.dgs-case-tags span { padding:8px 11px; border-radius:999px; font-size:12px; color:#36d6ff; background:rgba(54,214,255,.09); border:1px solid rgba(54,214,255,.22); }
.dgs-small-link { display:inline-flex; margin-top:24px; color:#fff !important; text-decoration:none !important; font-weight:800; padding:12px 18px; border-radius:12px; background:linear-gradient(135deg,#2f6bff,#f6c35b); box-shadow:0 14px 38px rgba(47,107,255,.22); transition:.3s ease; }
.dgs-small-link:hover { transform:translateY(-3px); }

/* Weavings Fixed Safe Preview */
.dgs-safe-preview-screen { position:relative; height:392px; overflow:hidden; background: radial-gradient(circle at 20% 20%, rgba(47,107,255,.28), transparent 28%), radial-gradient(circle at 80% 65%, rgba(54,214,255,.24), transparent 32%), linear-gradient(135deg,#111,#070707); padding:28px; }
.dgs-safe-preview-glow { position:absolute; inset:auto -20% -45% -20%; height:220px; background:linear-gradient(90deg,rgba(47,107,255,.28),rgba(246,195,91,.18),rgba(54,214,255,.25)); filter:blur(40px); }
.dgs-safe-topbar { width:62%; height:24px; border-radius:999px; background:rgba(255,255,255,.12); border:1px solid rgba(255,255,255,.12); margin-bottom:38px; }
.dgs-safe-hero-lines span { display:block; height:16px; border-radius:999px; background:rgba(255,255,255,.16); margin-bottom:14px; }
.dgs-safe-hero-lines span:nth-child(1){ width:84%; } .dgs-safe-hero-lines span:nth-child(2){ width:66%; } .dgs-safe-hero-lines span:nth-child(3){ width:46%; background:rgba(246,195,91,.22); }
.dgs-safe-preview-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; margin-top:38px; }
.dgs-safe-preview-grid span { height:72px; border-radius:16px; background:rgba(255,255,255,.075); border:1px solid rgba(255,255,255,.1); }
.dgs-safe-preview-message { position:absolute; right:24px; bottom:24px; left:24px; padding:18px; border-radius:18px; background:rgba(0,0,0,.68); border:1px solid rgba(255,255,255,.14); backdrop-filter:blur(12px); }
.dgs-safe-preview-message strong { display:block; font-size:18px; color:#fff; }
.dgs-safe-preview-message p { margin:8px 0 12px; font-size:13px; line-height:1.5; color:rgba(255,255,255,.68); }
.dgs-safe-preview-message a { color:#f6c35b !important; font-weight:800; text-decoration:none !important; }


/* Live Screenshot Preview For Iframe-Blocked Sites */
.dgs-mshot-preview { position:relative; }
.dgs-live-shot-link { position:relative; display:block; height:392px; overflow:hidden; background:#101010; text-decoration:none !important; }
.dgs-live-shot-link img { width:100%; height:100%; object-fit:cover; object-position:top center; display:block; transform:scale(1.01); transition:.55s ease; }
.dgs-live-shot-link:hover img { transform:scale(1.06); }
.dgs-live-shot-overlay { position:absolute; left:18px; right:18px; bottom:18px; padding:16px 18px; border-radius:18px; background:rgba(0,0,0,.72); border:1px solid rgba(255,255,255,.14); backdrop-filter:blur(14px); }
.dgs-live-shot-overlay strong { display:block; color:#fff; font-size:18px; margin-bottom:5px; }
.dgs-live-shot-overlay span { display:block; color:rgba(255,255,255,.66); font-size:13px; }

/* Playable Video Layout */
.dgs-playable-video-layout { display:grid; grid-template-columns:1.25fr .75fr; grid-template-rows:repeat(3, minmax(158px, 1fr)); gap:16px; min-height:620px; }
.dgs-playable-video { position:relative; overflow:hidden; border-radius:24px; background:#070707; border:1px solid rgba(255,255,255,.14); box-shadow:0 24px 70px rgba(0,0,0,.32); }
.dgs-playable-video.main-video { grid-row:span 3; }
.dgs-playable-video iframe { position:absolute; inset:0; width:100%; height:100%; border:0; display:block; background:#000; }
.dgs-video-caption { position:absolute; left:14px; right:14px; bottom:14px; padding:12px 14px; border-radius:16px; background:linear-gradient(135deg,rgba(0,0,0,.76),rgba(9,17,22,.68)); border:1px solid rgba(255,255,255,.12); backdrop-filter:blur(14px); pointer-events:none; }
.dgs-video-caption span { display:inline-flex; color:#f6c35b; font-size:10px; letter-spacing:1.2px; text-transform:uppercase; font-weight:900; margin-bottom:5px; }
.dgs-video-caption strong { display:block; color:#fff; font-size:15px; line-height:1.25; }
.dgs-avatar-section .dgs-ai-feature-case { background:linear-gradient(135deg,rgba(246,195,91,.09),rgba(47,107,255,.09),rgba(54,214,255,.06)); }
.dgs-ai-production-case { background:linear-gradient(135deg,rgba(54,214,255,.08),rgba(47,107,255,.07),rgba(246,195,91,.05)) !important; }

/* AI Video */
.dgs-ai-video-section { background: linear-gradient(180deg, transparent, rgba(47,107,255,.035), transparent); }
.dgs-ai-feature-case { display:grid; grid-template-columns:minmax(360px,.82fr) minmax(0,1.18fr); gap:28px; padding:26px; border-radius:30px; border:1px solid rgba(255,255,255,.12); background:linear-gradient(135deg,rgba(47,107,255,.10),rgba(246,195,91,.055),rgba(54,214,255,.045)); box-shadow:0 34px 110px rgba(0,0,0,.34); }
.dgs-ai-case-content { padding:20px; align-self:center; }
.dgs-ai-video-layout { display:grid; grid-template-columns:1.1fr .9fr; grid-template-rows:1fr 1fr 1fr; gap:16px; min-height:560px; }
.dgs-video-card { position:relative; border-radius:24px; overflow:hidden; border:1px solid rgba(255,255,255,.13); background:#111; box-shadow:0 18px 60px rgba(0,0,0,.28); }
.dgs-video-card.main-video { grid-row:span 3; }
.dgs-video-screen { position:relative; width:100%; height:100%; min-height:170px; display:flex; flex-direction:column; justify-content:flex-end; padding:22px; background: radial-gradient(circle at 50% 22%, rgba(246,195,91,.32), transparent 34%), radial-gradient(circle at 20% 78%, rgba(47,107,255,.26), transparent 36%), linear-gradient(145deg,#22120b,#080808 58%,#061013); }
.dgs-video-card.main-video .dgs-video-screen { min-height:560px; background: radial-gradient(circle at 50% 24%, rgba(246,195,91,.38), transparent 30%), radial-gradient(circle at 35% 62%, rgba(47,107,255,.30), transparent 34%), radial-gradient(circle at 80% 80%, rgba(54,214,255,.18), transparent 30%), linear-gradient(145deg,#241008,#090909 58%,#071117); }
.dgs-video-screen:before { content:""; position:absolute; inset:16px; border-radius:20px; border:1px solid rgba(255,255,255,.08); pointer-events:none; }
.dgs-play-button { position:absolute; top:22px; right:22px; width:52px; height:52px; border-radius:50%; background:linear-gradient(135deg,#2f6bff,#f6c35b); box-shadow:0 14px 36px rgba(47,107,255,.32); }
.dgs-play-button:after { content:""; position:absolute; left:21px; top:16px; border-left:15px solid #fff; border-top:10px solid transparent; border-bottom:10px solid transparent; }
.dgs-video-label { display:inline-flex; width:max-content; padding:7px 11px; border-radius:999px; color:#f6c35b; background:rgba(0,0,0,.42); border:1px solid rgba(246,195,91,.28); font-size:11px; letter-spacing:1.2px; text-transform:uppercase; font-weight:900; margin-bottom:12px; }
.dgs-video-screen h4 { position:relative; margin:0; font-size:clamp(20px,2.2vw,32px); line-height:1.1; }
.dgs-video-screen p { position:relative; margin:8px 0 0; color:rgba(255,255,255,.68); line-height:1.5; }
.dgs-ai-deliverables-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:16px; margin-top:26px; }
.dgs-ai-deliverables-grid div { padding:20px; border-radius:20px; background:rgba(255,255,255,.045); border:1px solid rgba(255,255,255,.1); }
.dgs-ai-deliverables-grid strong { display:block; color:#f6c35b; font-size:18px; margin-bottom:8px; }
.dgs-ai-deliverables-grid span { display:block; color:rgba(255,255,255,.68); line-height:1.6; font-size:14px; }

/* Service Cards */
.dgs-service-case-wrapper { background:linear-gradient(180deg,transparent,rgba(255,255,255,.018),transparent); }
.dgs-service-case-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:24px; }
.dgs-service-case-card, .dgs-process-card { padding:28px; border-radius:24px; border:1px solid rgba(255,255,255,.12); background:rgba(255,255,255,.035); transition:.35s ease; }
.dgs-service-case-card:hover, .dgs-process-card:hover { transform:translateY(-7px); border-color:rgba(47,107,255,.42); box-shadow:0 24px 70px rgba(47,107,255,.12); }
.dgs-service-icon { width:62px; height:62px; display:grid; place-items:center; margin-bottom:20px; border-radius:18px; background:linear-gradient(135deg,rgba(47,107,255,.22),rgba(246,195,91,.18)); border:1px solid rgba(246,195,91,.24); color:#f6c35b; font-weight:900; font-size:17px; }
.dgs-service-case-card h3 { font-size:28px; }
.dgs-cs-process-section { padding:80px 0; }
.dgs-process-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:22px; }
.dgs-process-card span { display:block; font-size:42px; font-weight:900; line-height:1; margin-bottom:20px; background:linear-gradient(135deg,#2f6bff,#f6c35b,#36d6ff); -webkit-background-clip:text; -webkit-text-fill-color:transparent; background-clip:text; opacity:.88; }
.dgs-process-card h3 { font-size:22px; }

/* CTA */
.dgs-cs-final-cta { padding:80px 0 110px; }
.dgs-final-cta-box { text-align:center; max-width:1020px; margin:0 auto; padding:64px 42px; border-radius:32px; background:radial-gradient(circle at 20% 20%,rgba(47,107,255,.20),transparent 35%), radial-gradient(circle at 80% 70%,rgba(54,214,255,.18),transparent 35%), linear-gradient(135deg,rgba(255,255,255,.08),rgba(255,255,255,.025)); border:1px solid rgba(255,255,255,.14); box-shadow:0 35px 120px rgba(0,0,0,.4); }
.dgs-final-cta-box h2 { font-size:clamp(32px,5vw,58px); }
.dgs-final-cta-box p { max-width:780px; margin:22px auto 30px; font-size:17px; }
.dgs-project-card.dgs-hidden { display:none !important; }

/* Responsive */
@media (max-width: 1180px) {
  .dgs-cs-hero-grid, .dgs-website-card, .dgs-ai-feature-case { grid-template-columns:1fr; }
  .dgs-cs-hero-visual { min-height:auto; }
  .dgs-hero-device { transform:rotateY(-5deg) rotateX(4deg); }
  .dgs-service-case-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .dgs-process-grid, .dgs-ai-deliverables-grid { grid-template-columns:repeat(2,minmax(0,1fr)); }
}
@media (max-width: 768px) {
  .dgs-cs-hero { padding:86px 0 54px; }
  .dgs-cs-hero h1 { letter-spacing:-1.4px; }
  .dgs-cs-hero p { font-size:16px; }
  .dgs-cs-hero-stats, .dgs-case-meta, .dgs-service-case-grid, .dgs-process-grid, .dgs-ai-deliverables-grid { grid-template-columns:1fr; }
  .dgs-hero-device { transform:none; border-radius:22px; }
  .dgs-floating-badge { display:none; }
  .dgs-website-card, .dgs-ai-feature-case { padding:18px; border-radius:22px; }
  .dgs-browser-preview { min-height:380px; }
  .dgs-iframe-wrap, .dgs-safe-preview-screen { height:332px; }
  .dgs-ai-video-layout, .dgs-playable-video-layout { grid-template-columns:1fr; grid-template-rows:auto; min-height:auto; }
  .dgs-video-card.main-video, .dgs-playable-video.main-video { grid-row:auto; }
  .dgs-video-card.main-video .dgs-video-screen, .dgs-video-screen { min-height:260px; }
  .dgs-playable-video { min-height:260px; }
  .dgs-live-shot-link { height:332px; }
  .dgs-cs-btn { width:100%; }
  .dgs-cs-hero-actions { width:100%; }
  .dgs-final-cta-box { padding:44px 22px; border-radius:24px; }
}
@media (max-width: 480px) {
  .dgs-dashboard-grid { grid-template-columns:1fr; }
  .dgs-device-screen { padding:18px; }
  .dgs-dashboard-bars { height:135px; }
  .dgs-browser-top p { display:none; }
  .dgs-website-content, .dgs-service-case-card, .dgs-process-card, .dgs-ai-case-content { padding:20px; }
  .dgs-website-content h3, .dgs-service-case-card h3, .dgs-ai-case-content h3 { font-size:25px; }
}


